package com.gomgomapps.math.core;
import java.util.*;import org.junit.Test;import static org.junit.Assert.*;
public class LargePracticalNumberStoriesTest {
 private static void verify(Question q,List<String> answers){q.answers=new String[]{"poison","poison"};q.expression="poison";Checker c=new Checker();assertTrue(c.check(q,List.of(),answers).correct());for(int i=0;i<answers.size();i++){List<String> wrong=new ArrayList<>(answers);String a=answers.get(i);wrong.set(i,Set.of("<","=",">").contains(a)?a.equals("=")?"<":"=":""+(Integer.parseInt(a)+1));Checker.Result result=c.check(q,List.of(),wrong);assertEquals(Checker.Status.WRONG_ANSWER,result.status);assertEquals(i,result.index);}HelpPlan h=HelpPlan.forQuestion(q);assertFalse(h.canTransfer());assertTrue(h.restore(null,q.id).entries.stream().allMatch(String::isEmpty));}
 @Test public void publicUpperBoundariesAndIndependentRoundingGrid(){
  for(int context=0;context<2;context++)for(int n:new int[]{0,1,9999,10000,99999,100000,999999,1000000,1000001,1234567,9999999,10000000}){Question q=PracticalPlaceStories.makeLarge(context,n);verify(q,List.of(""+n));int[] v=PracticalPlaceStories.readLarge(q);assertNotNull(v);HelpPlan h=HelpPlan.forQuestion(q);assertEquals(8,h.size());int unit=1000000;for(int i=0;i<7;i++,unit/=10)assertTrue(h.step(i).accepts(""+(v[i]*unit)));assertTrue(h.step(7).accepts(""+n));}
  for(int unit=10;unit<=10000000;unit*=10)for(int n:new int[]{0,1,unit/2-1,unit/2,unit/2+1,unit-1,unit,10000000-unit,9999999,10000000}){Question q=YearFiveNumberStories.rounding(n,unit);int expected=n/unit*unit+(n%unit>=unit/2?unit:0);verify(q,List.of(""+expected));HelpPlan h=HelpPlan.forQuestion(q);assertEquals(7,h.size());int base=n/unit*unit,digit=n%unit/(unit/10);List<String> entries=List.of(""+n,""+unit,""+digit,digit>=5?"raise":"keep",""+base,""+(expected-base),""+expected);for(int i=0;i<7;i++)assertTrue(h.step(i).accepts(entries.get(i)));}
  for(int unit=10;unit<=10000000;unit*=10)for(int n=0;n<10000000;n+=10001){int expected=n/unit*unit+(n%unit>=unit/2?unit:0);verify(YearFiveNumberStories.rounding(n,unit),List.of(""+expected));}
  for(int direction:new int[]{1,-1})for(int unit=10;unit<=1000000;unit*=10)for(int offset:new int[]{0,1,10000000-2*unit}){int start=offset+(direction<0?2*unit:0);verify(YearFiveNumberStories.stock(start,direction*unit),List.of(""+(start+direction*unit),""+(start+2*direction*unit)));}
  for(int a:new int[]{0,1,1000000,1000001,9999999,10000000})for(int b:new int[]{0,1,1000000,1000001,9999999,10000000})verify(YearFiveNumberStories.compare(a,b),List.of(a<b?"<":a>b?">":"="));
 }
 @Test public void indexedBoundariesAndActualYearSixSupplyPreserveLowerYears(){Generator g=new Generator(new Random(191));for(String id:List.of(PracticalPlaceStories.ID,YearFiveNumberStories.STOCK,YearFiveNumberStories.ROUND,YearFiveNumberStories.COMPARE)){if(!id.equals(PracticalPlaceStories.ID))assertTrue(GlobalCurriculum.limits("england-primary-2021-v1",id,6).allows(YearFiveNumberStories.atLarge(id,0)));List<String> recent=new ArrayList<>();boolean large=false;for(int i=0;i<150;i++){Question q=g.next(id,recent,false,GlobalCurriculum.limits("england-primary-2021-v1",id,6));assertFalse(recent.contains(q.signature()));recent.add(q.signature());if(id.equals(PracticalPlaceStories.ID)){int[] v=PracticalPlaceStories.readLarge(q);assertNotNull(v);large|=v[7]>1000000;}else{int[] v=YearFiveNumberStories.read(q);assertNotNull(v);large|=v[0]>1000000;assertTrue(Math.abs(v[0])<=10000000);}if(!q.kind.equals("symbol"))assertTrue(q.choices.isEmpty());}assertTrue(large);if(!id.equals(PracticalPlaceStories.ID)){long size=YearFiveNumberStories.largeCount(id);for(long index:new long[]{0,1,size/2,size-2,size-1})assertNotNull(YearFiveNumberStories.read(YearFiveNumberStories.atLarge(id,index)));}}
  for(int grade=3;grade<=5;grade++)for(int i=0;i<25;i++){Question q=g.next(PracticalPlaceStories.ID,List.of(),false,GlobalCurriculum.limits("england-primary-2021-v1",PracticalPlaceStories.ID,grade));assertNull(PracticalPlaceStories.readLarge(q));}
  for(String id:List.of(YearFiveNumberStories.STOCK,YearFiveNumberStories.ROUND,YearFiveNumberStories.COMPARE))for(int i=0;i<50;i++){int[] v=YearFiveNumberStories.read(g.next(id,List.of(),false,GlobalCurriculum.limits("england-primary-2021-v1",id,5)));assertTrue(v[0]<=1000000);if(id.equals(YearFiveNumberStories.COMPARE))assertTrue(v[1]<=1000000);}
 }
 @Test public void longIndexedWrapAndPublicInvalidInputs(){long count=100000020000001L;Random random=new Random(){@Override public long nextLong(){return 2*(count-1);}};java.util.function.LongFunction<Question> factory=i->{assertTrue(i>=0&&i<count);return new Question("count","index "+i,"","0");};Map<String,Integer> recent=new HashMap<>();recent.put(factory.apply(count-1).signature(),0);Question q=IndexedQuestionSupply.chooseLarge(count,factory,random,CurriculumLimits.NONE,recent);assertEquals(factory.apply(0).signature(),q.signature());
  q=PracticalPlaceStories.makeLarge(0,10000000);q.prompt=q.prompt.replace("낱개: 0","낱개: 1");assertNull(PracticalPlaceStories.readLarge(q));assertEquals(Checker.Status.INPUT_NEEDED,new Checker().check(q,List.of(),List.of("10000001")).status);
  for(String id:List.of(YearFiveNumberStories.COMPARE,YearFiveNumberStories.ROUND)){q=id.equals(YearFiveNumberStories.COMPARE)?YearFiveNumberStories.compare(10000000,0):YearFiveNumberStories.rounding(10000000,10000000);q.prompt=q.prompt.replaceFirst("10000000","10000001");assertNull(YearFiveNumberStories.read(q));assertEquals(Checker.Status.INPUT_NEEDED,new Checker().check(q,List.of(),List.of("0")).status);}
 }
}
